  function isSpace(ev) {
    return ev.key === ' ' || ev.key === 'Spacebar' || ev.code === 'Space';
  }
  function isArrow(ev) {
    return ev.key === 'ArrowUp' || ev.key === 'ArrowDown' || ev.key === 'ArrowLeft' || ev.key === 'ArrowRight';
