/*!
 * SnakeGame.render —— Canvas 渲染与界面反馈（架构契约 v1 · §2.5）
 * 只读 game 与最高分：不修改游戏状态、不推进逻辑。
 */
(function (root) {
  'use strict';

  var ns = root.SnakeGame = root.SnakeGame || {};

  var CELL = 24;          // 20×20 网格，每格 24px
  var GRID = 20;
  var SIZE = CELL * GRID; // 480×480

  var COLORS = {
    background: '#0b0f14',
    gridLine: 'rgba(148, 163, 184, 0.12)',
    border: 'rgba(148, 163, 184, 0.35)',
    snakeBody: '#22c55e',
    snakeBodyAlt: '#16a34a',
    snakeHead: '#86efac',
    snakeEye: '#0b0f14',
    food: '#f97316',
    foodGlow: 'rgba(249, 115, 22, 0.45)'
  };

  function isFiniteNumber(v) { return typeof v === 'number' && isFinite(v); }

  function createRenderer(opts) {
    opts = opts || {};
    var canvas = opts.canvas || null;
    var scoreEl = opts.scoreEl || null;
    var highScoreEl = opts.highScoreEl || null;
    var statusEl = opts.statusEl || null;

    var ctx = null;
    if (canvas && typeof canvas.getContext === 'function') {
      try { ctx = canvas.getContext('2d'); } catch (err) { ctx = null; }
    }

    var dprApplied = 0;
    var lastGame = null;
    var lastHighScore = 0;

    function syncCanvas() {...}

    function updatePanel(el, value) {
      if (!el) return;
      var text = String(value);
      if (el.textContent !== text) el.textContent = text;
    }

    function drawBackground() {
      ctx.fillStyle = COLORS.background;
      ctx.fillRect(0, 0, SIZE, SIZE);
      ctx.strokeStyle = COLORS.gridLine;
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (var i = 1; i < GRID; i++) {
        var p = i * CELL + 0.5;  // 0.5 对齐，避免线条发虚
        ctx.moveTo(p, 0); ctx.lineTo(p, SIZE);
        ctx.moveTo(0, p); ctx.lineTo(SIZE, p);
      }
      ctx.stroke();
      ctx.strokeStyle = COLORS.border;
      ctx.strokeRect(0.5, 0.5, SIZE - 1, SIZE - 1);
    }
```

Hmm, lineWidth 1 at p=24 gives blurry; 24.5 crisp. With dpr transform, half-pixel alignment works at dpr>=1. Let me use p = i*CELL + 0.5.

